def find_reachable_values(n, k, coins):
    reachable = {0}

    for coin in coins:
        if coin > k:
            continue
        new_reachable = reachable.copy()
        for r in reachable:
            if r + coin <= k:
                new_reachable.add(r + coin)
        reachable.update(new_reachable)

    return sorted(reachable)

