def find_possible_values(n, k, coins):
    dp = [False] * (k + 1)
    dp[0] = True

    for coin in coins:
        for j in range(k, coin - 1, -1):
            if dp[j - coin]:
                dp[j] = True

    possible_sums = set()

    def dfs(index, current_sum):
        if index == n:
            return

        dfs(index + 1, current_sum)
        if current_sum <= k:
            dfs(index + 1, current_sum + coins[index])
            possible_sums.add(current_sum)

    dfs(0, 0)

    return sorted(list(possible_sums))

